    return { id: e.id, score, strongHits, rare, terms: hit };
  }).sort((a, b) => b.score - a.score);
}
// Returns the card that best addresses the specific claim, or null to keep the current pick.
function siphonSpecificPick(side, kind, sentence, currentId) {
  const ranked = siphonSpecificScores(side, kind, sentence);
  const top = ranked[0];
  if (!top || top.score <= 0) return null;
  const confident = top.score >= 3.2 && (top.strongHits >= 2 || top.rare);
  if (!confident) return null;
  const second = ranked[1];
  if (!currentId) {
    // nothing triggered: only fill in when one card clearly stands out
    if (second && top.score < second.score * 1.25) return null;
    return top;
  }
  if (top.id === currentId) return null;
  const cur = ranked.find(r => r.id === currentId);
  const curScore = cur ? cur.score : 0;
  // switch only when the other card is clearly more specific to what they said
  if (top.score >= curScore + 1.5 && top.score >= curScore * 1.35) return top;
  return null;
}

